/* Lossless complete arrays observed in both original public cave passes.
 * Each case retains explicit prefix and first/restored/changed references.
 * Reused-output equality describes only these captured cases. */
typedef struct caves_byte_run {
    uint32_t count;
    uint8_t value;
} caves_byte_run;

typedef struct caves_block_fixture {
    size_t offset;
    size_t count;
} caves_block_fixture;

typedef struct caves_case_fixture {
    int64_t seed;
    int32_t chunk_x;
    int32_t chunk_z;
    caves_block_fixture arrays[4];
    uint64_t following[3][4];
    size_t changed[3];
    bool relationships[3];
} caves_case_fixture;

